/// <summary>
/// AVA
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(LedgerAllocationRuleDestination, AVACreateBasisFromDestination), FormControlEventType::Clicked)]
public static void AVACreateBasisFromDestination_OnClicked(FormControl sender, FormControlEventArgs e)
{
    MainAccountNum                                  mainAccount;
    LedgerDefaultDimensionValueSet                  dimSet;
    AVALedgerAllocCreateBasisRuleFromDestination    createBasisRuleFromDesination;

    LedgerAllocationRuleDestination destination = sender.formRun().dataSource(formDataSourceStr(LedgerAllocationRuleDestination,LedgerAllocationRuleDestination)).cursor();
    mainAccount = destination.AVARuleSourceAccountNum;
    dimSet      = destination.ToDefaultDimension;

    if (!destination.BasisId)
    {
        createBasisRuleFromDesination = AVALedgerAllocCreateBasisRuleFromDestination::construct(destination.RuleID);
        createBasisRuleFromDesination.parmMainAccount(mainAccount);
        createBasisRuleFromDesination.parmDimSet(dimSet);
        destination.BasisId = createBasisRuleFromDesination.createBasisRule();
        sender.formRun().dataSource(FormDataSourcestr(LedgerAllocationRuleDestination,LedgerAllocationRuleDestination)).research(true);
    }

}
